def preserve_existing_channel_intent(apps, schema_editor):
    CommerceIntake = apps.get_model('commerce', 'CommerceIntake')
    CommerceIntake.objects.filter(ordering_mode='preorder').update(sales_channel='online')
def preserve_existing_product_publication(apps, schema_editor):
    StorefrontProduct = apps.get_model('commerce', 'StorefrontProduct')
    production_verticals = ('bakery', 'restaurant', 'general')
    StorefrontProduct.objects.update(allow_distribution_order=False, allow_online_order=False)
    StorefrontProduct.objects.filter(business__vertical__in=production_verticals).update(allow_online_order=F('allow_preorder'))
def seed_commerce_order_sequences(apps, schema_editor):
    CommerceIntake = apps.get_model('commerce', 'CommerceIntake')
    CommerceOrderNumberSequence = apps.get_model('commerce', 'CommerceOrderNumberSequence')
    highest_by_business = {}
    for business_id, public_number in CommerceIntake.objects.exclude(public_number='').values_list('business_id', 'public_number'):
        prefix, separator, suffix = public_number.rpartition('-')
        if separator and prefix == 'WEB' and suffix.isdigit():
            highest_by_business[business_id] = max(highest_by_business.get(business_id, 0), int(suffix))
    for business_id, highest in highest_by_business.items():
        CommerceOrderNumberSequence.objects.update_or_create(business_id=business_id, defaults={'next_number': highest + 1})
def mark_existing_notifications_processed(apps, schema_editor):
    CommerceNotification = apps.get_model('commerce', 'CommerceNotification')
    CommerceNotification.objects.filter(push_processed_at__isnull=True).update(push_processed_at=django.utils.timezone.now())
def populate_receipt_public_ids(apps, schema_editor):
    """Assign a distinct UUID to every pre-existing receipt before uniqueness is enforced.

    Adding a non-null unique field with a callable default in a single schema step is
    unsafe on populated SQLite tables because the table-remake path can evaluate the
    default once and reuse it for every copied row. Populate explicitly first, then
    make the field non-null/unique in the following AlterField operation.
    """
    Receipt = apps.get_model('commerce', 'CommercePaymentReceipt')
    database_alias = schema_editor.connection.alias
    queryset = Receipt.objects.using(database_alias).filter(public_id__isnull=True).only('pk')
    batch = []
    seen = set()
    for receipt in queryset.iterator(chunk_size=500):
        candidate = uuid.uuid4()
        while candidate in seen:
            candidate = uuid.uuid4()
        seen.add(candidate)
        receipt.public_id = candidate
        batch.append(receipt)
        if len(batch) >= 500:
            Receipt.objects.using(database_alias).bulk_update(batch, ['public_id'], batch_size=500)
            batch.clear()
    if batch:
        Receipt.objects.using(database_alias).bulk_update(batch, ['public_id'], batch_size=500)

